mapper.select:
SELECT c.id, c.note_id AS noteId, n.title AS noteTitle, c.user_id AS userId, u.username, u.avatar, c.parent_id AS parentId, c.reply_to_user_id AS replyToUserId, ru.username AS replyToUsername, c.reply_to_comment_id AS replyToCommentId, c.content, c.is_deleted AS isDeleted, c.created_at AS createdAt, c.updated_at AS updatedAt FROM t_comment c LEFT JOIN t_note_item n ON c.note_id = n.id LEFT JOIN t_user u ON c.user_id = u.id LEFT JOIN t_user ru ON c.reply_to_user_id = ru.id
AND (c.content LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR ru.username LIKE CONCAT('%', #{keyword}, '%') OR n.title LIKE CONCAT('%', #{keyword}, '%'))
AND c.is_deleted = #{isDeleted}
AND c.created_at >= #{startTime}
AND c.created_at <= #{endTime}
ORDER BY c.created_at DESC, c.id DESC
